def process_rhs(self, compiler, connection):
    if isinstance(self.rhs, Query):
        # If rhs is some Query, don't touch it.
        return super().process_rhs(compiler, connection)
    if isinstance(self.rhs, Expression):
        self.rhs = self.rhs.resolve_expression(compiler.query)
    rhs, rhs_params = super().process_rhs(compiler, connection)
    placeholder = connection.ops.get_geom_placeholder(self.lhs.output_field, self.rhs, compiler)
    return placeholder % rhs, rhs_params

def now():
    """
    Return an aware or naive datetime.datetime, depending on settings.USE_TZ.
    """
    if settings.USE_TZ:
        # timeit shows that datetime.now(tz=utc) is 24% slower
        return datetime.utcnow().replace(tzinfo=utc)
    else:
        return datetime.now()

def rotate_token(request):
    """
    Change the CSRF token in use for a request - should be done on login
    for security purposes.
    """
    request.META.update({
        "CSRF_COOKIE_USED": True,
        "CSRF_COOKIE": _get_new_csrf_token(),
    })
    request.csrf_cookie_needs_reset = True

def get(self, request, *args, **kwargs):
    url = self.get_redirect_url(*args, **kwargs)
    if url:
        if self.permanent:
            return HttpResponsePermanentRedirect(url)
        else:
            return HttpResponseRedirect(url)
    else:
        logger.warning(
            'Gone: %s', request.path,
            extra={'status_code': 410, 'request': request}
        )
        return HttpResponseGone()

def chararray_output(func, argtypes, errcheck=True):
    """For functions that return a c_char_p array."""
    func.argtypes = argtypes
    func.restype = POINTER(c_char_p)
    if errcheck:
        func.errcheck = check_pointer
    return func

def render(self, context):
    from pprint import pformat
    output = [pformat(val) for val in context]
    output.append('\n\n')
    output.append(pformat(sys.modules))
    return ''.join(output)

def migration_plan(self, targets, clean_start=False):
    """
    Given a set of targets, return a list of (Migration instance, backwards?).
    """
    plan = []
    if clean_start:
        applied = set()
    else:
        applied = set(self.loader.applied_migrations)
    for target in targets:
        # If the target is (app_label, None), that means unmigrate everything
        if target[1] is None:
            for root in self.loader.graph.root_nodes():
                if root[0] == target[0]:
                    for migration in self.loader.graph.backwards_plan(root):
                        if migration in applied:
                            plan.append((self.loader.graph.nodes[migration], True))
                            applied.remove(migration)
        # If the migration is already applied, do backwards mode,
        # otherwise do forwards mode.
        elif target in applied:
            # Don't migrate backwards all the way to the target node (that
            # may roll back dependencies in other apps that don't need to
            # be rolled back); instead roll back through target's immediate
            # child(ren) in the same app, and no further.
            next_in_app = sorted(
                n for n in
                self.loader.graph.node_map[target].children
                if n[0] == target[0]
            )
            for node in next_in_app:
                for migration in self.loader.graph.backwards_plan(node):
                    if migration in applied:
                        plan.append((self.loader.graph.nodes[migration], True))
                        applied.remove(migration)
        else:
            for migration in self.loader.graph.forwards_plan(target):
                if migration not in applied:
                    plan.append((self.loader.graph.nodes[migration], False))
                    applied.add(migration)
    return plan

def value_omitted_from_data(self, data, files, name):
    return (
        super().value_omitted_from_data(data, files, name) and
        self.clear_checkbox_name(name) not in data
    )

def to_python(self, value):
    if isinstance(value, str):
        # Assume we're deserializing
        vals = json.loads(value)
        for end in ('lower', 'upper'):
            if end in vals:
                vals[end] = self.base_field.to_python(vals[end])
        value = self.range_type(**vals)
    elif isinstance(value, (list, tuple)):
        value = self.range_type(value[0], value[1])
    return value

@classmethod
def get_email_field_name(cls):
    try:
        return cls.EMAIL_FIELD
    except AttributeError:
        return 'email'

def __init__(self, expression, srid, **extra):
    expressions = [
        expression,
        self._handle_param(srid, 'srid', int),
    ]
    if 'output_field' not in extra:
        extra['output_field'] = GeometryField(srid=srid)
    super().__init__(*expressions, **extra)

def get_db_converters(self, expression):
    converters = super().get_db_converters(expression)
    if isinstance(expression.output_field, GeometryField):
        converters.append(self.get_geometry_converter(expression))
    return converters

def deconstruct(self):
    kwargs = {
        'model_name': self.model_name,
        'name': self.name,
    }
    return (
        self.__class__.__name__,
        [],
        kwargs
    )

def __copy__(self):
    result = self.__class__('', mutable=True, encoding=self.encoding)
    for key, value in self.lists():
        result.setlist(key, value)
    return result

@requires_csrf_token
def permission_denied(request, exception, template_name=ERROR_403_TEMPLATE_NAME):
    """
    Permission denied (403) handler.

    Templates: :template:`403.html`
    Context: None

    If the template does not exist, an Http403 response containing the text
    "403 Forbidden" (as per RFC 7231) will be returned.
    """
    try:
        template = loader.get_template(template_name)
    except TemplateDoesNotExist:
        if template_name != ERROR_403_TEMPLATE_NAME:
            # Reraise if it's a missing custom template.
            raise
        return HttpResponseForbidden('<h1>403 Forbidden</h1>', content_type='text/html')
    return HttpResponseForbidden(
        template.render(request=request, context={'exception': str(exception)})
    )

@classmethod
def WithData(cls, original_exc, model, fk, field_value):
    """
    Factory method for creating a deserialization error which has a more
    explanatory message.
    """
    return cls("%s: (%s:pk=%s) field_value was '%s'" % (original_exc, model, fk, field_value))

def _print_LeviCivita(self, expr, exp=None):
    indices = map(self._print, expr.args)
    if all(x.is_Atom for x in expr.args):
        tex = r'\varepsilon_{%s}' % " ".join(indices)
    else:
        tex = r'\varepsilon_{%s}' % ", ".join(indices)
    if exp:
        tex = r'\left(%s\right)^{%s}' % (tex, exp)
    return tex

def _dup_decompose(f, K):
    """Helper function for :func:`dup_decompose`."""
    df = len(f) - 1

    for s in range(2, df):
        if df % s != 0:
            continue

        h = _dup_right_decompose(f, s, K)

        if h is not None:
            g = _dup_left_decompose(f, h, K)

            if g is not None:
                return g, h

    return None

@staticmethod
def Mul(expr, assumptions):
    """
    Integer*Integer      -> Integer
    Integer*Irrational   -> !Integer
    Odd/Even             -> !Integer
    Integer*Rational     -> ?
    """
    if expr.is_number:
        return AskIntegerHandler._number(expr, assumptions)
    _output = True
    for arg in expr.args:
        if not ask(Q.integer(arg), assumptions):
            if arg.is_Rational:
                if arg.q == 2:
                    return ask(Q.even(2*expr), assumptions)
                if ~(arg.q & 1):
                    return None
            elif ask(Q.irrational(arg), assumptions):
                if _output:
                    _output = False
                else:
                    return
            else:
                return
    else:
        return _output

def visit_Num(self, node):
    if isinstance(node.n, int):
        return fix_missing_locations(Call(Name('Integer', Load()),
                [node], [], None, None))
    elif isinstance(node.n, float):
        return fix_missing_locations(Call(Name('Float', Load()),
            [node], [], None, None))
    return node

def dmp_primitive_prs(f, g, u, K):
    """
    Primitive polynomial remainder sequence (PRS) in `K[X]`.

    Examples
    ========

    >>> from sympy.polys import ring, ZZ
    >>> R, x,y = ring("x,y", ZZ)

    """
    if not u:
        return dup_primitive_prs(f, g, K)
    else:
        raise MultivariatePolynomialError(f, g)

def _eval_is_negative(self):
    n = self.args[0]
    if n.is_integer and n.is_positive:
        if n.is_odd:
            return False
        return (n / 2).is_odd

@staticmethod
def Add(expr, assumptions):
    if all(ask(Q.positive(x), assumptions) for x in expr.args) \
            or all(ask(Q.negative(x), assumptions) for x in expr.args):
        return True

def fdiff(self, argindex=4):
    if argindex == 1:
        # Diff wrt n
        raise ArgumentIndexError(self, argindex)
    elif argindex == 2:
        # Diff wrt m
        raise ArgumentIndexError(self, argindex)
    elif argindex == 3:
        # Diff wrt theta
        n, m, theta, phi = self.args
        return (m * cot(theta) * Ynm(n, m, theta, phi) +
                sqrt((n - m)*(n + m + 1)) * exp(-I*phi) * Ynm(n, m + 1, theta, phi))
    elif argindex == 4:
        # Diff wrt phi
        n, m, theta, phi = self.args
        return I * m * Ynm(n, m, theta, phi)
    else:
        raise ArgumentIndexError(self, argindex)

def get_numbered_constants(eq, num=1, start=1, prefix='C'):
    """
    Returns a list of constants that do not occur
    in eq already.
    """

    if isinstance(eq, Expr):
        eq = [eq]
    elif not iterable(eq):
        raise ValueError("Expected Expr or iterable but got %s" % eq)

    atom_set = set().union(*[i.free_symbols for i in eq])
    ncs = numbered_symbols(start=start, prefix=prefix, exclude=atom_set)
    Cs = [next(ncs) for i in range(num)]
    return (Cs[0] if num == 1 else tuple(Cs))

def __new__(cls, *args, **kwargs):
    # Points are sequences, but they should not
    # be converted to Tuples, so use this detection function instead.
    def is_seq_and_not_point(a):
        # we cannot use isinstance(a, Point) since we cannot import Point
        if hasattr(a, 'is_Point') and a.is_Point:
            return False
        return is_sequence(a)

    args = [Tuple(*a) if is_seq_and_not_point(a) else sympify(a) for a in args]
    return Basic.__new__(cls, *args)

def reset(self):
    self.result = {'encoding': None, 'confidence': 0.0}
    self.done = False
    self._mStart = True
    self._mGotData = False
    self._mInputState = ePureAscii
    self._mLastChar = b''
    if self._mEscCharSetProber:
        self._mEscCharSetProber.reset()
    for prober in self._mCharSetProbers:
        prober.reset()

def get_confidence(self):
    r = 0.01
    if self._mTotalSeqs > 0:
        r = ((1.0 * self._mSeqCounters[POSITIVE_CAT]) / self._mTotalSeqs
             / self._mModel['mTypicalPositiveRatio'])
        r = r * self._mFreqChar / self._mTotalChar
        if r >= 1.0:
            r = 0.99
    return r

def get_confidence(self):
    st = self.get_state()
    if st == constants.eFoundIt:
        return 0.99
    elif st == constants.eNotMe:
        return 0.01
    bestConf = 0.0
    self._mBestGuessProber = None
    for prober in self._mProbers:
        if not prober:
            continue
        if not prober.active:
            if constants._debug:
                sys.stderr.write(prober.get_charset_name()
                                 + ' not active\n')
            continue
        cf = prober.get_confidence()
        if constants._debug:
            sys.stderr.write('%s confidence = %s\n' %
                             (prober.get_charset_name(), cf))
        if bestConf < cf:
            bestConf = cf
            self._mBestGuessProber = prober
    if not self._mBestGuessProber:
        return 0.0
    return bestConf

@property
def request_uri(self):
    """Absolute path including the query string."""
    uri = self.path or '/'

    if self.query is not None:
        uri += '?' + self.query

    return uri

def iter_lines(self, chunk_size=ITER_CHUNK_SIZE, decode_unicode=None):
    """Iterates over the response data, one line at a time.  When
    stream=True is set on the request, this avoids reading the
    content at once into memory for large responses.
    """

    pending = None

    for chunk in self.iter_content(chunk_size=chunk_size, decode_unicode=decode_unicode):

        if pending is not None:
            chunk = pending + chunk
        lines = chunk.splitlines()

        if lines and lines[-1] and chunk and lines[-1][-1] == chunk[-1]:
            pending = lines.pop()
        else:
            pending = None

        for line in lines:
            yield line

    if pending is not None:
        yield pending

def get_cookie_header(jar, request):
    """Produce an appropriate Cookie header string to be sent with `request`, or None."""
    r = MockRequest(request)
    jar.add_cookie_header(r)
    return r.get_new_headers().get('Cookie')

def request_encode_url(self, method, url, fields=None, **urlopen_kw):
    """
    Make a request using :meth:`urlopen` with the ``fields`` encoded in
    the url. This is useful for request methods like GET, HEAD, DELETE, etc.
    """
    if fields:
        url += '?' + urlencode(fields)
    return self.urlopen(method, url, **urlopen_kw)

def get_redirect_location(self):
    """
    Should we redirect and where to?

    :returns: Truthy redirect location string if we got a redirect status
        code and valid location. ``None`` if redirect status and no
        location. ``False`` if not a redirect status code.
    """
    if self.status in self.REDIRECT_STATUSES:
        return self.headers.get('location')

    return False

@staticmethod
def _encode_files(files, data):
    """Build the body for a multipart/form-data request.

    Will successfully encode files when passed as a dict or a list of
    2-tuples. Order is retained if data is a list of 2-tuples but arbitrary
    if parameters are supplied as a dict.

    """
    if (not files):
        raise ValueError("Files must be provided.")
    elif isinstance(data, basestring):
        raise ValueError("Data must not be a string.")

    new_fields = []
    fields = to_key_val_list(data or {})
    files = to_key_val_list(files or {})

    for field, val in fields:
        if isinstance(val, basestring) or not hasattr(val, '__iter__'):
            val = [val]
        for v in val:
            if v is not None:
                # Don't call str() on bytestrings: in Py3 it all goes wrong.
                if not isinstance(v, bytes):
                    v = str(v)

                new_fields.append(
                    (field.decode('utf-8') if isinstance(field, bytes) else field,
                     v.encode('utf-8') if isinstance(v, str) else v))

    for (k, v) in files:
        # support for explicit filename
        ft = None
        fh = None
        if isinstance(v, (tuple, list)):
            if len(v) == 2:
                fn, fp = v
            elif len(v) == 3:
                fn, fp, ft = v
            else:
                fn, fp, ft, fh = v
        else:
            fn = guess_filename(v) or k
            fp = v
        if isinstance(fp, str):
            fp = StringIO(fp)
        if isinstance(fp, bytes):
            fp = BytesIO(fp)

        rf = RequestField(name=k, data=fp.read(),
                          filename=fn, headers=fh)
        rf.make_multipart(content_type=ft)
        new_fields.append(rf)

    body, content_type = encode_multipart_formdata(new_fields)

    return body, content_type

def get_encoding_from_headers(headers):
    """Returns encodings from given HTTP Header Dict.

    :param headers: dictionary to extract encoding from.
    """

    content_type = headers.get('content-type')

    if not content_type:
        return None

    content_type, params = cgi.parse_header(content_type)

    if 'charset' in params:
        return params['charset'].strip("'\"")

    if 'text' in content_type:
        return 'ISO-8859-1'

def __setstate__(self, state):
    # Can't handle by adding 'proxy_manager' to self.__attrs__ because
    # because self.poolmanager uses a lambda function, which isn't pickleable.
    self.proxy_manager = {}
    self.config = {}

    for attr, value in state.items():
        setattr(self, attr, value)

    self.init_poolmanager(self._pool_connections, self._pool_maxsize,
                          block=self._pool_block)

def decompress(self, data):
    if not self._first_try:
        return self._obj.decompress(data)

    self._data += data
    try:
        return self._obj.decompress(data)
    except zlib.error:
        self._first_try = False
        self._obj = zlib.decompressobj(-zlib.MAX_WBITS)
        try:
            return self.decompress(self._data)
        finally:
            self._data = None

def prepare_cookies(self, cookies):
    """Prepares the given HTTP cookie data."""

    if isinstance(cookies, cookielib.CookieJar):
        self._cookies = cookies
    else:
        self._cookies = cookiejar_from_dict(cookies)

    cookie_header = get_cookie_header(self._cookies, self)
    if cookie_header is not None:
        self.headers['Cookie'] = cookie_header

def dispatch_hook(key, hooks, hook_data, **kwargs):
    """Dispatches a hook dictionary on a given piece of data."""

    hooks = hooks or dict()

    if key in hooks:
        hooks = hooks.get(key)

        if hasattr(hooks, '__call__'):
            hooks = [hooks]

        for hook in hooks:
            _hook_data = hook(hook_data, **kwargs)
            if _hook_data is not None:
                hook_data = _hook_data

    return hook_data

def json(self, **kwargs):
    """Returns the json-encoded content of a response, if any.

    :param \*\*kwargs: Optional arguments that ``json.loads`` takes.
    """

    if not self.encoding and len(self.content) > 3:
        # No encoding set. JSON RFC 4627 section 3 states we should expect
        # UTF-8, -16 or -32. Detect which one to use; If the detection or
        # decoding fails, fall back to `self.text` (using chardet to make
        # a best guess).
        encoding = guess_json_utf(self.content)
        if encoding is not None:
            try:
                return json.loads(self.content.decode(encoding), **kwargs)
            except UnicodeDecodeError:
                # Wrong UTF codec detected; usually because it's not UTF-8
                # but some other 8-bit codec.  This is an RFC violation,
                # and the server didn't bother to tell us what codec *was*
                # used.
                pass
    return json.loads(self.text, **kwargs)

def get_load_dotenv(default: bool = True) -> bool:
    """Get whether the user has disabled loading dotenv files by setting
    :envvar:`FLASK_SKIP_DOTENV`. The default is ``True``, load the
    files.

    :param default: What to return if the env var isn't set.
    """
    val = os.environ.get("FLASK_SKIP_DOTENV")

    if not val:
        return default

    return val.lower() in ("0", "false", "no")

def default(self, o: t.Any) -> t.Any:
    """Convert ``o`` to a JSON serializable type. See
    :meth:`json.JSONEncoder.default`. Python does not support
    overriding how basic types like ``str`` or ``list`` are
    serialized, they are handled before this method.
    """
    if isinstance(o, date):
        return http_date(o)
    if isinstance(o, uuid.UUID):
        return str(o)
    if dataclasses and dataclasses.is_dataclass(o):
        return dataclasses.asdict(o)
    if hasattr(o, "__html__"):
        return str(o.__html__())
    return super().default(o)

def make_setup_state(
    self, app: "Flask", options: dict, first_registration: bool = False
) -> BlueprintSetupState:
    """Creates an instance of :meth:`~flask.blueprints.BlueprintSetupState`
    object that is later passed to the register callback functions.
    Subclasses can override this to return a subclass of the setup state.
    """
    return BlueprintSetupState(self, app, options, first_registration)

def __repr__(self) -> str:
    return (
        f"<{type(self).__name__} {self.request.url!r}"
        f" [{self.request.method}] of {self.app.name}>"
    )

def on_json_loading_failed(self, e: Exception) -> "te.NoReturn":
    if current_app and current_app.debug:
        raise BadRequest(f"Failed to decode JSON object: {e}")

    raise BadRequest()

def handle_url_build_error(
    self, error: Exception, endpoint: str, values: dict
) -> str:
    """Handle :class:`~werkzeug.routing.BuildError` on
    :meth:`url_for`.
    """
    for handler in self.url_build_error_handlers:
        try:
            rv = handler(error, endpoint, values)
        except BuildError as e:
            # make error available outside except block
            error = e
        else:
            if rv is not None:
                return rv

    # Re-raise if called with an active exception, otherwise raise
    # the passed in exception.
    if error is sys.exc_info()[1]:
        raise

    raise error

def _dump_loader_info(loader) -> t.Generator:
    yield f"class: {type(loader).__module__}.{type(loader).__name__}"
    for key, value in sorted(loader.__dict__.items()):
        if key.startswith("_"):
            continue
        if isinstance(value, (tuple, list)):
            if not all(isinstance(x, str) for x in value):
                continue
            yield f"{key}:"
            for item in value:
                yield f"  - {item}"
            continue
        elif not isinstance(value, (str, int, float, bool)):
            continue
        yield f"{key}: {value!r}"

def _get_source_explained(
    self, environment: Environment, template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable]]:
    attempts = []
    rv: t.Optional[t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]]
    trv: t.Optional[
        t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]
    ] = None

    for srcobj, loader in self._iter_loaders(template):
        try:
            rv = loader.get_source(environment, template)
            if trv is None:
                trv = rv
        except TemplateNotFound:
            rv = None
        attempts.append((loader, srcobj, rv))

    from .debughelpers import explain_template_loading_attempts

    explain_template_loading_attempts(self.app, template, attempts)

    if trv is not None:
        return trv
    raise TemplateNotFound(template)

def app_context_processor(
    self, f: TemplateContextProcessorCallable
) -> TemplateContextProcessorCallable:
    """Like :meth:`Flask.context_processor` but for a blueprint.  Such a
    function is executed each request, even if outside of the blueprint.
    """
    self.record_once(
        lambda s: s.app.template_context_processors.setdefault(None, []).append(f)
    )
    return f

def setupmethod(f: t.Callable) -> t.Callable:
    """Wraps a method so that it performs a check in debug mode if the
    first request was already handled.
    """

    def wrapper_func(self, *args: t.Any, **kwargs: t.Any) -> t.Any:
        if self._is_setup_finished():
            raise AssertionError(
                "A setup function was called after the first request "
                "was handled. This usually indicates a bug in the"
                " application where a module was not imported and"
                " decorators or other functionality was called too"
                " late.\nTo fix this make sure to import all your view"
                " modules, database models, and everything related at a"
                " central place before the application starts serving"
                " requests."
            )
        return f(self, *args, **kwargs)

    return update_wrapper(wrapper_func, f)

def ensure_sync(self, func: t.Callable) -> t.Callable:
    """Ensure that the function is synchronous for WSGI workers.
    Plain ``def`` functions are returned as-is. ``async def``
    functions are wrapped to run and wait for the response.

    Override this method to change how the app runs async views.

    .. versionadded:: 2.0
    """
    if iscoroutinefunction(func):
        return self.async_to_sync(func)

    return func

def auto_pop(self, exc: t.Optional[BaseException]) -> None:
    if self.request.environ.get("flask._preserve_context") or (
        exc is not None and self.app.preserve_context_on_exception
    ):
        self.preserved = True
        self._preserved_exc = exc  # type: ignore
    else:
        self.pop(exc)

def get_include():
    """
    Get the path to astropy.wcs's C header files.
    """
    import os
    return os.path.join(os.path.dirname(__file__), "include")

def __array_wrap__(self, array, context=None):
    """
    Wrapper for multiplication with numpy arrays.
    """
    if type(context[0]) == np.ufunc:
        return NotImplemented
    else:
        return array

def attach_zero_velocities(coord):
    """
    Set the differentials to be stationary on a coordinate object.
    """
    new_data = coord.cartesian.with_differentials(ZERO_VELOCITIES)
    return coord.realize_frame(new_data)

@classmethod
def _format_unit_list(cls, units):
    out = []
    units.sort(key=lambda x: cls._get_unit_name(x[0]).lower())

    for base, power in units:
        if power == 1:
            out.append(cls._get_unit_name(base))
        else:
            power = utils.format_power(power)
            if '/' in power or '.' in power:
                out.append(f'{cls._get_unit_name(base)}({power})')
            else:
                out.append(f'{cls._get_unit_name(base)}{power}')
    return ' '.join(out)

@property
def input_units(self):
    if self.translation.unit is None and self.matrix.unit is None:
