@staticmethod
def _uncertain_nodes_in_try_blocks_when_evaluating_finally_blocks(
    found_nodes: List[nodes.NodeNG], node_statement: nodes.Statement
) -> List[nodes.NodeNG]:
    uncertain_nodes: List[nodes.NodeNG] = []
    (
        closest_try_finally_ancestor,
        child_of_closest_try_finally_ancestor,
    ) = utils.get_node_first_ancestor_of_type_and_its_child(
        node_statement, nodes.TryFinally
    )
    if closest_try_finally_ancestor is None:
        return uncertain_nodes
    if (
        child_of_closest_try_finally_ancestor
        not in closest_try_finally_ancestor.finalbody
    ):
        return uncertain_nodes
    for other_node in found_nodes:
        other_node_statement = other_node.statement(future=True)
        (
            other_node_try_finally_ancestor,
            child_of_other_node_try_finally_ancestor,
        ) = utils.get_node_first_ancestor_of_type_and_its_child(
            other_node_statement, nodes.TryFinally
        )
        if other_node_try_finally_ancestor is None:
            continue
        # other_node needs to descend from the try of a try/finally.
        if (
            child_of_other_node_try_finally_ancestor
            not in other_node_try_finally_ancestor.body
        ):
            continue
        # If the two try/finally ancestors are not the same, then
        # node_statement's closest try/finally ancestor needs to be in
        # the final body of other_node's try/finally ancestor, or
        # descend from one of the statements in that final body.
        if (
            other_node_try_finally_ancestor is not closest_try_finally_ancestor
            and not any(
                other_node_final_statement is closest_try_finally_ancestor
                or other_node_final_statement.parent_of(
                    closest_try_finally_ancestor
                )
                for other_node_final_statement in other_node_try_finally_ancestor.finalbody
            )
        ):
            continue
        # Passed all tests for uncertain execution
        uncertain_nodes.append(other_node)
    return uncertain_nodes

@utils.check_messages(
    "misplaced-bare-raise",
    "raising-bad-type",
    "raising-non-exception",
    "notimplemented-raised",
    "bad-exception-context",
    "raising-format-tuple",
    "raise-missing-from",
)
def visit_raise(self, node: nodes.Raise) -> None:
    if node.exc is None:
        self._check_misplaced_bare_raise(node)
        return

    if node.cause is None:
        self._check_raise_missing_from(node)
    else:
        self._check_bad_exception_context(node)

    expr = node.exc
    ExceptionRaiseRefVisitor(self, node).visit(expr)

    try:
        inferred_value = expr.inferred()[-1]
    except astroid.InferenceError:
        pass
    else:
        if inferred_value:
            ExceptionRaiseLeafVisitor(self, node).visit(inferred_value)

@_sympifyit('other', NotImplemented)
@call_highest_priority('__rpow__')
def __pow__(self, other):
    if other != 1 and not self.is_square:
        raise ShapeError("Power of non-square matrix %s" % self)
    if other == 0:
        return Identity(self.rows)
    if other < 1:
        raise ValueError("Matrix det == 0; not invertible.")
    return self

def _get_permissions(self, user_obj, obj, from_name):
    """
    Return the permissions of `user_obj` from `from_name`. `from_name` can
    be either "group" or "user" to return permissions from
    `_get_group_permissions` or `_get_user_permissions` respectively.
    """
    if not user_obj.is_active or user_obj.is_anonymous or obj is not None:
        return set()

    perm_cache_name = '_%s_perm_cache' % from_name
    if not hasattr(user_obj, perm_cache_name):
        if user_obj.is_superuser:
            perms = Permission.objects.all()
        else:
            perms = getattr(self, '_get_%s_permissions' % from_name)(user_obj)
        perms = perms.values_list('content_type__app_label', 'codename').order_by()
        setattr(user_obj, perm_cache_name, {"%s.%s" % (ct, name) for ct, name in perms})
    return getattr(user_obj, perm_cache_name)

def roots(self):
    """
    Returns the total number of roots of E_n
    """

    n = self.n
    if n == 6:
        return 72
    if n == 7:
        return 126
    if n == 8:
        return 240

def clean_fields(self, exclude=None):
    """
    Clean all fields and raise a ValidationError containing a dict
    of all validation errors if any occur.
    """
    if exclude is None:
        exclude = []

    errors = {}
    for f in self._meta.fields:
        if f.name in exclude:
            continue
        # Skip validation for empty fields with blank=True. The developer
        # is responsible for making sure they have a valid value.
        raw_value = getattr(self, f.attname)
        if f.blank and raw_value in f.empty_values:
            continue
        try:
            setattr(self, f.attname, f.clean(raw_value, self))
        except ValidationError as e:
            errors[f.name] = e.error_list

    if errors:
        raise ValidationError(errors)

def gf_add(f, g, p, K):
    """
    Add polynomials in ``GF(p)[x]``.

    Examples
    ========

    >>> from sympy.polys.domains import ZZ
    >>> from sympy.polys.galoistools import gf_add

    >>> gf_add([3, 2, 4], [2, 2, 2], 5, ZZ)
    [4, 1]

    """
    if not f:
        return g
    if not g:
        return f

    df = gf_degree(f)
    dg = gf_degree(g)

    if df == dg:
        return gf_strip([ (a + b) % p for a, b in zip(f, g) ])
    else:
        k = abs(df - dg)

        if df > dg:
            h, f = f[:k], f[k:]
        else:
            h, g = g[:k], g[k:]

        return h + [ (a + b) % p for a, b in zip(f, g) ]

@function_helper
def einsum(subscripts, *operands, out=None, **kwargs):
    from astropy.units import Quantity

    if not isinstance(subscripts, str):
        raise ValueError('only "subscripts" string mode supported for einsum.')

    if out is not None:
        if not isinstance(out, Quantity):
            raise NotImplementedError

        else:
            kwargs['out'] = out.view(np.ndarray)

    qs = _as_quantities(*operands)
    unit = functools.reduce(operator.mul, (q.unit for q in qs),
                            dimensionless_unscaled)
    arrays = tuple(q.view(np.ndarray) for q in qs)
    return (subscripts,) + arrays, kwargs, unit, out

def __pow__(self, other):
    # Implements only power to an integer.
    from .lib_interval import exp, log
    if not self.is_valid:
        return self
    if isinstance(other, interval):
        return exp(other * log(self))
    elif isinstance(other, (float, int)):
        if other < 0:
            return 1 / self.__pow__(abs(other))
        else:
            if int(other) == other:
                return _pow_int(self, other)
            else:
                return _pow_float(self, other)
    else:
        return NotImplemented

def get_id(self, version: int, objectType: str = None, symbol: "Symbol" = None) -> str:
    # this is not part of the normal name mangling in C++
    if symbol:
        # the anchor will be our parent
        return symbol.parent.declaration.get_id(version, prefixed=False)
    # else, do the usual
    if self.ellipsis:
        return 'z'
    else:
        return self.arg.get_id(version)

