def encode_string(s: str) -> str:
    def replace(match: Match) -> str:
        s = match.group(0)
        try:
            if s == '\\':
                return '\\\\'
            elif s == '"':
                return '\\"'
            elif s == '\x08':
                return '\\b'
            elif s == '\x0c':
                return '\\f'
            elif s == '\n':
                return '\\n'
            elif s == '\r':
                return '\\r'
            elif s == '\t':
                return '\\t'
            raise KeyError(s)
        except KeyError:
            n = ord(s)
            if n < 0x10000:
                return '\\u%04x' % (n,)
            else:
                # surrogate pair
                n -= 0x10000
                s1 = 0xd800 | ((n >> 10) & 0x3ff)
                s2 = 0xdc00 | (n & 0x3ff)
                return '\\u%04x\\u%04x' % (s1, s2)
    return '"' + str(ESCAPE_ASCII.sub(replace, s)) + '"'

