@frame_transform_graph.transform(DynamicMatrixTransform, FK5, Galactic)
def fk5_to_gal(fk5coord, galframe):
    # need precess to J2000 first
    pmat = fk5coord._precession_matrix(fk5coord.equinox, EQUINOX_J2000)
    mat1 = rotation_matrix(180 - Galactic._lon0_J2000.degree, 'z')
    mat2 = rotation_matrix(90 - Galactic._ngp_J2000.dec.degree, 'y')
    mat3 = rotation_matrix(Galactic._ngp_J2000.ra.degree, 'z')

    if pmat is not None:
        if mat1 is not None:
            if mat2 is not None:
                if mat3 is not None:
                    return matrix_product(mat1, mat2, mat3, pmat)
                else:
                    return matrix_product(mat1, mat2, None, pmat)
            else:
                return matrix_product(mat1, None, mat3, pmat)
        else:
            return matrix_product(None, mat2, mat3, pmat)
    else:
        return matrix_product(mat1, mat2, mat3, None)

def _is_type_checking_import(node: Union[nodes.Import, nodes.ImportFrom]) -> bool:
    """Check if an import node is guarded by a TYPE_CHECKS guard."""
    result = False
    ancestors = list(node.node_ancestors())
    i = 0
    while i < len(ancestors):
        ancestor = ancestors[i]
        if isinstance(ancestor, nodes.If):
            test_str = ancestor.test.as_string()
            if test_str in TYPING_TYPE_CHECKS_GUARDS:
                result = True
                break
            else:
                pass
        else:
            pass
        i += 1
    return result

