def get_fontext_synonyms(fontext):
    """
    Return a list of file extensions extensions that are synonyms for
    the given file extension *fileext*.
    """
    if fontext == 'afm':
        return ['afm']
    elif fontext == 'otf':
        return ['otf', 'ttc', 'ttf']
    elif fontext == 'ttc':
        return ['otf', 'ttc', 'ttf']
    elif fontext == 'ttf':
        return ['otf', 'ttc', 'ttf']

def _netcdf_to_numpy_timeunit(units):
    units = units.lower()
    if not units.endswith("s"):
        units = "%ss" % units
    if units == "microseconds":
        return "us"
    elif units == "milliseconds":
        return "ms"
    elif units == "seconds":
        return "s"
    elif units == "minutes":
        return "m"
    elif units == "hours":
        return "h"
    elif units == "days":
        return "D"

def parse(self, dot: str = None) -> None:
    matched = self.maptag_re.match(self.content[0])
    if not matched:
        raise GraphvizError('Invalid clickable map file found: %s' % self.filename)

    self.id = matched.group(1)
    if self.id == '%3':
        # graphviz generates wrong ID if graph name not specified
        # https://gitlab.com/graphviz/graphviz/issues/1327
        hashed = sha1(dot.encode()).hexdigest()
        self.id = 'grapviz%s' % hashed[-10:]
        self.content[0] = self.content[0].replace('%3', self.id)

    for line in self.content:
        # This checks if the href pattern matches the current line
        if self.href_re.search(line):
            # This appends the line to the clickable list if it matches
            self.clickable.append(line)

def _create_nan_agg_method(name, coerce_strings=False):
    from . import nanops

    def f(values, axis=None, skipna=None, **kwargs):
        if kwargs.pop("out", None) is not None:
            raise TypeError("`out` is not valid for {}".format(name))

        # Convert input to array using asarray
        values = asarray(values)

        # If coercion is enabled and data is string-like, cast to object array
        if coerce_strings and values.dtype.kind in "SU":
            values = values.astype(object)

        # Initialize function placeholder
        func = None

        # Determine whether to use nan-aware function based on skipna and dtype
        if skipna or (skipna is None and values.dtype.kind in "cfO"):
            nanname = "nan" + name
            func = getattr(nanops, nanname)
        else:
            func = _dask_or_eager_func(name)

        # Attempt to call the function with given arguments
        try:
            return func(values, axis=axis, **kwargs)
        except AttributeError:
            # Handle special case for dask arrays needing dtype argument
            if isinstance(values, dask_array_type):
                try:  # dask/dask#3133 dask sometimes needs dtype argument
                    # If func does not accept dtype, then raises TypeError
                    return func(values, axis=axis, dtype=values.dtype, **kwargs)
                except (AttributeError, TypeError):
                    msg = "%s is not yet implemented on dask arrays" % name
            else:
                msg = (
                    "%s is not available with skipna=False with the "
                    "installed version of numpy; upgrade to numpy 1.12 "
                    "or newer to use skipna=True or skipna=None" % name
                )
            raise NotImplementedError(msg)

    f.__name__ = name
    return f

def get_parent_list(self):
    """
    Return all the ancestors of this model as a list ordered by MRO.
    Useful for determining if something is an ancestor, regardless of lineage.
    """
    result = OrderedSet(self.parents)
    # Adding each parent to the result set
    for parent in self.parents:
        # Getting the parent's own ancestor list from its meta options
        for ancestor in parent._meta.get_parent_list():
            # Adding each found ancestor to the result set
            result.add(ancestor)
    return list(result)

